import React from "react";
import { TextField, Button, MenuItem, Chip } from "@mui/material";
import { motion } from "framer-motion";
import { AddCircleOutline } from "@mui/icons-material";

export default function ExtraCitiesSelector({
  formData,
  availableExtraCities,
  handleAddExtraCity,
  handleRemoveExtraCity,
  setFormData,
}) {
  return (
    <>
      <TextField
        fullWidth
        label="Selecciona ciudad"
        select
        value={formData.extraCityInput}
        onChange={(e) =>
          setFormData((prev) => ({
            ...prev,
            extraCityInput: e.target.value,
          }))
        }
      >
        {availableExtraCities.map((city) => (
          <MenuItem key={city} value={city}>
            {city}
          </MenuItem>
        ))}
      </TextField>

      {formData.extraCityInput === "Otro" && (
        <TextField
          fullWidth
          label="Especifica la ciudad"
          name="customExtraCity"
          value={formData.customExtraCity}
          onChange={(e) =>
            setFormData((prev) => ({
              ...prev,
              customExtraCity: e.target.value,
            }))
          }
        />
      )}

      <Button
        onClick={handleAddExtraCity}
        variant="contained"
        startIcon={<AddCircleOutline />}
        className="mt-2 bg-purple-600 hover:bg-purple-700 text-white"
      >
        Añadir ciudad
      </Button>

      <div className="flex flex-wrap gap-2 pt-2">
        {formData.selectedExtraCities.map((city) => (
          <motion.div
            key={city}
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ duration: 0.3 }}
          >
            <Chip
              label={city}
              onDelete={() => handleRemoveExtraCity(city)}
              color="secondary"
              className="shadow-lg hover:scale-105 transition-transform"
            />
          </motion.div>
        ))}
      </div>
    </>
  );
}
