import React from "react";
import { TextField, Chip, Typography } from "@mui/material";
import { motion } from "framer-motion";

export default function InterpretationCitiesSelector({
  formData,
  handleInterpretationCityInputChange,
  handleInterpretationCityKeyDown,
  handleRemoveInterpretationCity,
}) {
  return (
    <>
      <Typography className="pt-4 font-medium text-purple-800">
        Ciudades donde necesitas la interpretación
      </Typography>

      <TextField
        fullWidth
        label="Escribe y presiona Enter"
        placeholder="Ej: Pekín, Shanghái, etc."
        value={formData.interpretationCityInput}
        onChange={(e) => handleInterpretationCityInputChange(e.target.value)}
        onKeyDown={handleInterpretationCityKeyDown}
      />

      <div className="flex flex-wrap gap-2 pt-2">
        {formData.selectedInterpretationCities.map((city) => (
          <motion.div
            key={city}
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ duration: 0.3 }}
          >
            <Chip
              label={city}
              onDelete={() => handleRemoveInterpretationCity(city)}
              color="secondary"
              className="shadow-lg hover:scale-105 transition-transform"
            />
          </motion.div>
        ))}
      </div>
    </>
  );
}
