import React, { useEffect } from "react";
import {
  Modal,
  Box,
  Typography,
  TextField,
  Checkbox,
  FormControlLabel,
  IconButton,
} from "@mui/material";
import {
  Close,
  Translate,
  Tour,
  CheckCircle,
  Navigation,
  NearMe,
} from "@mui/icons-material";
import { motion } from "framer-motion";
import AOS from "aos";
import "aos/dist/aos.css";

import { useReservationForm } from "../hook/useReservationForm";
import ExtraCitiesSelector from "./ExtraCitiesSelector";
import InterpretationCitiesSelector from "./InterpretationCitiesSelector";
import InterpretationTypesSelector from "./InterpretationTypesSelector";

const ReservationModal = ({ tour, onClose }) => {
  const {
    formData,
    setFormData,
    isInterpretation,
    isSubmitted,
    isSending,
    availableExtraCities,
    INTERPRETATION_TYPES,
    handleChange,
    handleCheckbox,
    handleAddExtraCity,
    handleRemoveExtraCity,
    handleInterpretationCityInputChange,
    handleInterpretationCityKeyDown,
    handleRemoveInterpretationCity,
    handleAddInterpretationType,
    handleRemoveInterpretationType,
    handleSubmit,
  } = useReservationForm(tour, onClose);

  useEffect(() => {
    AOS.init({ duration: 600 });
  }, []);

  return (
    <Modal open={true} onClose={onClose}>
      <Box
        display="flex"
        alignItems="center"
        justifyContent="center"
        height="100vh"
        px={1}
      >
        <Box
          className="bg-gradient-to-br from-purple-100 via-white to-purple-50 rounded-3xl p-4 sm:p-8 w-full sm:max-w-2xl mx-auto shadow-2xl border-4 border-purple-200 relative"
          data-aos="zoom-in-up"
          sx={{
            outline: "none",
            maxHeight: "90vh",
            overflowY: "auto",
          }}
        >
          <IconButton
            onClick={onClose}
            sx={{ position: "absolute", top: 16, right: 16 }}
          >
            <Close />
          </IconButton>

          {!isSubmitted ? (
            <motion.form
              initial={{ opacity: 0, y: -50 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6 }}
              className="space-y-5 pb-4"
              onSubmit={handleSubmit}
            >
              <Typography
                variant="h5"
                className="font-bold text-purple-800 flex items-center gap-2"
              >
                {isInterpretation ? <Translate /> : <Tour />}
                Reserva de {isInterpretation ? "Interpretación" : "Tour"}
              </Typography>

              <TextField
                label="Nombre completo"
                fullWidth
                name="name"
                value={formData.name}
                onChange={handleChange}
                required
              />
              <TextField
                label="Correo electrónico"
                fullWidth
                name="email"
                value={formData.email}
                onChange={handleChange}
                required
                type="email"
              />
              <TextField
                type="date"
                label="Fecha de inicio"
                fullWidth
                name="startDate"
                value={formData.startDate}
                onChange={handleChange}
                InputLabelProps={{ shrink: true }}
                required
              />
              <TextField
                type="date"
                label="Fecha de fin"
                fullWidth
                name="endDate"
                value={formData.endDate}
                onChange={handleChange}
                InputLabelProps={{ shrink: true }}
                required
              />

              {!isInterpretation ? (
                <>
                  <FormControlLabel
                    control={
                      <Checkbox
                        checked={formData.showCities}
                        onChange={handleCheckbox}
                        color="primary"
                      />
                    }
                    label="¿Deseas añadir ciudades adicionales?"
                  />
                  {formData.showCities && (
                    <ExtraCitiesSelector
                      formData={formData}
                      availableExtraCities={availableExtraCities}
                      handleAddExtraCity={handleAddExtraCity}
                      handleRemoveExtraCity={handleRemoveExtraCity}
                      setFormData={setFormData}
                    />
                  )}
                </>
              ) : (
                <>
                  <InterpretationCitiesSelector
                    formData={formData}
                    handleInterpretationCityInputChange={
                      handleInterpretationCityInputChange
                    }
                    handleInterpretationCityKeyDown={
                      handleInterpretationCityKeyDown
                    }
                    handleRemoveInterpretationCity={
                      handleRemoveInterpretationCity
                    }
                  />
                  <InterpretationTypesSelector
                    formData={formData}
                    INTERPRETATION_TYPES={INTERPRETATION_TYPES}
                    handleChange={handleChange}
                    handleAddInterpretationType={handleAddInterpretationType}
                    handleRemoveInterpretationType={
                      handleRemoveInterpretationType
                    }
                  />
                </>
              )}

              <motion.button
                type="submit"
                disabled={isSending}
                whileTap={{ scale: 0.97 }}
                className={`w-full py-3 px-6 rounded-xl font-bold text-white transition-all duration-500 shadow-lg ${
                  isSending
                    ? "bg-gray-400 cursor-not-allowed"
                    : "bg-gradient-to-r from-yellow-500 to-pink-500 hover:from-yellow-600 hover:to-pink-600 shadow-xl hover:shadow-2xl"
                }`}
              >
                {isSending ? "Enviando..." : "Enviar reserva"}
                {isSending ? (
                  <Navigation className="w-4 h-4 ml-2 inline-block" />
                ) : (
                  <NearMe className="w-4 h-4 ml-2 inline-block" />
                )}
              </motion.button>
            </motion.form>
          ) : (
            <motion.div
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ duration: 0.6 }}
              className="text-center text-purple-800"
            >
              <CheckCircle className="text-green-500" sx={{ fontSize: 60 }} />
              <Typography variant="h6" className="mt-2 font-bold">
                ¡Reserva enviada con éxito!
              </Typography>
              <Typography variant="body2">
                Nos pondremos en contacto pronto.
              </Typography>
            </motion.div>
          )}
        </Box>
      </Box>
    </Modal>
  );
};

export default ReservationModal;
