import React, { useState, useRef } from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";
import Modal from "@mui/material/Modal";
import { IconButton } from "@mui/material";
import { Cancel, CameraEnhanceOutlined } from "@mui/icons-material";
import { useSpring, animated } from "@react-spring/web";
import galleryMessage from "../mock/galleryMessage";

const GalleryMessage = () => {
  const [open, setOpen] = useState(false);
  const [selectedImage, setSelectedImage] = useState(null);
  const sliderRef = useRef(null);

  const modalFade = useSpring({
    opacity: open ? 1 : 0,
    config: { duration: 300 },
  });

  const handleImageClick = (imageUrl) => {
    setSelectedImage(imageUrl);
    setOpen(true);
  };

  const handleCloseModal = () => {
    setOpen(false);
    setSelectedImage(null);
  };

  const handleBeforeChange = () => {
    if (document.activeElement instanceof HTMLElement) {
      document.activeElement.blur();
    }
  };

  const settings = {
    centerMode: true,
    centerPadding: "5px", // Mucho menos padding para evitar espacio extra
    slidesToShow: 3,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 2000,
    dots: true,
    beforeChange: handleBeforeChange,
    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 2,
          centerPadding: "5px", // Consistente en tablet
          dots: true,
        },
      },
      {
        breakpoint: 768,
        settings: {
          arrows: false,
          centerMode: true,
          centerPadding: "3px", // Aún menos padding para móviles
          slidesToShow: 1,
          dots: false,
        },
      },
      {
        breakpoint: 480,
        settings: {
          arrows: false,
          centerMode: true,
          centerPadding: "3px",
          slidesToShow: 1,
          dots: false,
        },
      },
    ],
  };

  return (
    <section id="galleryMessage" className="py-16 max-w-full overflow-x-hidden">
      <div className="text-center lg:mb-8 mb-2 px-[5%]">
        <div className="inline-block relative group">
          <h2
            className="text-4xl md:text-5xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 via-pink-500 to-red-600 tracking-wide flex items-center justify-center gap-2"
            data-aos="zoom-in-up"
            data-aos-duration="600"
          >
            <CameraEnhanceOutlined
              className="w-6 h-6 text-yellow-400 animate-bounce mr-2"
              fontSize="large"
            />
            Retroalimentación de nuestros viajeros
            <CameraEnhanceOutlined
              className="w-6 h-6 text-yellow-400 animate-bounce ml-2"
              fontSize="large"
            />
          </h2>
        </div>
        {/*<p
          className="mt-4 text-white max-w-3xl mx-auto text-base sm:text-lg font-medium italic leading-relaxed"
          data-aos="fade-up"
          data-aos-duration="700"
        >
          Algunas imágenes de las reseñas de nuestros viajeros, que comparten
          sus experiencias y momentos inolvidables en sus viajes.
        </p>*/}
      </div>

      <div id="Carousel" className="overflow-hidden h-[300px] rounded-x1">
        <Slider ref={sliderRef} {...settings}>
          {galleryMessage.map((item, index) => (
            <img
              key={index}
              src={item.image}
              alt={`Imagen ${index + 1}`}
              onClick={() => handleImageClick(item.image)}
              style={{ cursor: "pointer", outline: "none" }}
            />
          ))}
        </Slider>
      </div>

      <Modal
        open={open}
        onClose={handleCloseModal}
        aria-labelledby="image-modal"
        aria-describedby="image-modal-description"
        className="flex justify-center items-center p-4 sm:p-6"
      >
        <animated.div
          style={{
            ...modalFade,
            maxWidth: "90vw",
            maxHeight: "90vh",
            width: "100%",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            position: "relative",
            borderRadius: "16px",
            overflow: "hidden",
            backgroundColor: "white",
          }}
          className="shadow-lg"
        >
          <IconButton
            edge="end"
            color="inherit"
            onClick={handleCloseModal}
            aria-label="close"
            sx={{
              position: "absolute",
              top: 12,
              right: 12,
              backgroundColor: "white",
              borderRadius: "50%",
              zIndex: 10,
            }}
          >
            <Cancel />
          </IconButton>

          {selectedImage && (
            <img
              src={selectedImage}
              alt="Imagen seleccionada"
              style={{
                maxWidth: "100%",
                maxHeight: "calc(90vh - 48px)",
                objectFit: "contain",
                borderRadius: "16px",
              }}
            />
          )}
        </animated.div>
      </Modal>
    </section>
  );
};

export default GalleryMessage;
