import React from "react";
import { TextField, Button, MenuItem, Chip } from "@mui/material";
import { motion } from "framer-motion";
import { AddCircleOutline } from "@mui/icons-material";

export default function InterpretationTypesSelector({
  formData,
  INTERPRETATION_TYPES,
  handleChange,
  handleAddInterpretationType,
  handleRemoveInterpretationType,
}) {
  return (
    <>
      <TextField
        fullWidth
        label="Tipo de interpretación"
        name="interpretationTypeInput"
        select
        value={formData.interpretationTypeInput}
        onChange={handleChange}
      >
        {INTERPRETATION_TYPES.filter(
          (type) => !formData.selectedInterpretationTypes.includes(type)
        ).map((type) => (
          <MenuItem key={type} value={type}>
            {type}
          </MenuItem>
        ))}
      </TextField>

      {formData.interpretationTypeInput === "Otro" && (
        <TextField
          fullWidth
          label="Especifica el tipo de servicio"
          name="customInterpretationType"
          value={formData.customInterpretationType}
          onChange={handleChange}
        />
      )}

      <Button
        onClick={handleAddInterpretationType}
        variant="contained"
        startIcon={<AddCircleOutline />}
        className="bg-purple-600 hover:bg-purple-700 text-white"
      >
        Añadir tipo
      </Button>

      <div className="flex flex-wrap gap-2 pt-2">
        {formData.selectedInterpretationTypes.map((type) => (
          <motion.div
            key={type}
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ duration: 0.3 }}
          >
            <Chip
              label={type}
              onDelete={() => handleRemoveInterpretationType(type)}
              color="primary"
              className="shadow-lg hover:scale-105 transition-transform"
            />
          </motion.div>
        ))}
      </div>
    </>
  );
}
