import { useState, useEffect } from "react";
import emailjs from "emailjs-com";

const EXTRA_CITY_LIST = [
  "Xi'an",
  "Guilin",
  "Cantón",
  "Chengdu",
  "Shanghái",
  "Otro",
];
const INTERPRETATION_TYPES = [
  "En tiempo real",
  "Acompañamiento a fábrica",
  "Redacción de texto",
  "Otro",
];

export function useReservationForm(tour, onClose) {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    startDate: "",
    endDate: "",
    showCities: false,
    extraCityInput: "",
    customExtraCity: "",
    selectedExtraCities: [],
    interpretationCityInput: "",
    selectedInterpretationCities: [],
    interpretationTypeInput: "",
    customInterpretationType: "",
    selectedInterpretationTypes: [],
  });

  const [isSubmitted, setIsSubmitted] = useState(false);
  const [isSending, setIsSending] = useState(false);

  const isInterpretation = tour?.type === "Interpretation";

  // Handlers básicos
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleCheckbox = (e) => {
    setFormData((prev) => ({ ...prev, showCities: e.target.checked }));
  };

  // Extra Cities
  const handleAddExtraCity = () => {
    const city =
      formData.extraCityInput === "Otro"
        ? formData.customExtraCity.trim()
        : formData.extraCityInput;
    if (city && !formData.selectedExtraCities.includes(city)) {
      setFormData((prev) => ({
        ...prev,
        selectedExtraCities: [...prev.selectedExtraCities, city],
        extraCityInput: "",
        customExtraCity: "",
      }));
    }
  };
  const handleRemoveExtraCity = (cityToRemove) => {
    setFormData((prev) => ({
      ...prev,
      selectedExtraCities: prev.selectedExtraCities.filter(
        (city) => city !== cityToRemove
      ),
    }));
  };
  const availableExtraCities = EXTRA_CITY_LIST.filter(
    (city) => !formData.selectedExtraCities.includes(city)
  );

  // Interpretation Cities
  const handleInterpretationCityInputChange = (value) => {
    setFormData((prev) => ({ ...prev, interpretationCityInput: value }));
  };
  const handleAddInterpretationCity = () => {
    const city = formData.interpretationCityInput.trim();
    if (city && !formData.selectedInterpretationCities.includes(city)) {
      setFormData((prev) => ({
        ...prev,
        selectedInterpretationCities: [
          ...prev.selectedInterpretationCities,
          city,
        ],
        interpretationCityInput: "",
      }));
    }
  };
  const handleInterpretationCityKeyDown = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      handleAddInterpretationCity();
    }
  };
  const handleRemoveInterpretationCity = (cityToRemove) => {
    setFormData((prev) => ({
      ...prev,
      selectedInterpretationCities: prev.selectedInterpretationCities.filter(
        (city) => city !== cityToRemove
      ),
    }));
  };

  // Interpretation Types
  const handleAddInterpretationType = () => {
    const type =
      formData.interpretationTypeInput === "Otro"
        ? formData.customInterpretationType.trim()
        : formData.interpretationTypeInput;
    if (type && !formData.selectedInterpretationTypes.includes(type)) {
      setFormData((prev) => ({
        ...prev,
        selectedInterpretationTypes: [
          ...prev.selectedInterpretationTypes,
          type,
        ],
        interpretationTypeInput: "",
        customInterpretationType: "",
      }));
    }
  };
  const handleRemoveInterpretationType = (typeToRemove) => {
    setFormData((prev) => ({
      ...prev,
      selectedInterpretationTypes: prev.selectedInterpretationTypes.filter(
        (type) => type !== typeToRemove
      ),
    }));
  };

  // Validación simple
  const isFormValid = () => {
    return (
      formData.name.trim() !== "" &&
      formData.email.trim() !== "" &&
      formData.startDate !== "" &&
      formData.endDate !== ""
    );
  };

  // Envío de formulario
  const handleSubmit = (e) => {
    e.preventDefault();
    if (!isFormValid()) return;
    setIsSending(true);

    const templateParams = {
      from_name: formData.name,
      from_email: formData.email,
      start_date: formData.startDate,
      end_date: formData.endDate,
      service_type: isInterpretation ? "Interpretación" : "Tour",
      extra_cities: formData.selectedExtraCities.join(", "),
      interpretation_cities: formData.selectedInterpretationCities.join(", "),
      interpretation_types: formData.selectedInterpretationTypes.join(", "),
    };

    emailjs
      .send(
        "smtp_126_com",
        "template_xdl2oxh",
        templateParams,
        "pzhHRfLyK6EyDiEcf"
      )
      .then(
        (response) => {
          console.log("Correo enviado", response);
          setIsSending(false);
          setIsSubmitted(true);
          setTimeout(() => {
            setIsSubmitted(false);
            onClose();
          }, 2500);
        },
        (error) => {
          console.error("Error al enviar correo", error);
          setIsSending(false);
          alert("Hubo un problema al enviar tu reserva. Inténtalo más tarde.");
        }
      );
  };

  return {
    formData,
    setFormData,
    isInterpretation,
    isSubmitted,
    isSending,
    availableExtraCities,
    INTERPRETATION_TYPES,
    handleChange,
    handleCheckbox,
    handleAddExtraCity,
    handleRemoveExtraCity,
    handleInterpretationCityInputChange,
    handleAddInterpretationCity,
    handleInterpretationCityKeyDown,
    handleRemoveInterpretationCity,
    handleAddInterpretationType,
    handleRemoveInterpretationType,
    handleSubmit,
    isFormValid,
  };
}
