import React, { useEffect, useState } from "react";

/**
 * TypingText: Componente con efecto de tipeo animado y estilo visual o blanco según configuración.
 * @param {Object} props
 * @param {string[]} props.words - Lista de frases a mostrar.
 * @param {number} [props.typingSpeed=100] - Velocidad de tipeo.
 * @param {number} [props.deletingSpeed=50] - Velocidad de borrado.
 * @param {number} [props.pauseTime=1000] - Tiempo de pausa entre palabras.
 * @param {boolean} [props.useGradient=true] - Define si se aplica estilo degradado o blanco.
 */
const TypingText = ({
  words,
  typingSpeed = 100,
  deletingSpeed = 50,
  pauseTime = 1000,
  useGradient = true,
}) => {
  const [text, setText] = useState("");
  const [wordIndex, setWordIndex] = useState(0);
  const [charIndex, setCharIndex] = useState(0);
  const [isDeleting, setIsDeleting] = useState(false);

  useEffect(() => {
    const currentWord = words[wordIndex];
    const speed = isDeleting ? deletingSpeed : typingSpeed;

    const timeout = setTimeout(() => {
      const updatedText = isDeleting
        ? currentWord.substring(0, charIndex - 1)
        : currentWord.substring(0, charIndex + 1);

      setText(updatedText);
      setCharIndex(isDeleting ? charIndex - 1 : charIndex + 1);

      if (!isDeleting && updatedText === currentWord) {
        setTimeout(() => setIsDeleting(true), pauseTime);
      }

      if (isDeleting && updatedText === "") {
        setIsDeleting(false);
        setWordIndex((prevIndex) => (prevIndex + 1) % words.length);
      }
    }, speed);

    return () => clearTimeout(timeout);
  }, [
    charIndex,
    isDeleting,
    wordIndex,
    words,
    typingSpeed,
    deletingSpeed,
    pauseTime,
  ]);

  return (
    <p
      className={`max-w-4xl mx-auto text-center font-medium drop-shadow-lg px-4
        text-base sm:text-lg md:text-xl lg:text-2xl xl:text-3xl
        ${
          useGradient
            ? "text-transparent bg-clip-text bg-gradient-to-r from-yellow-300 via-pink-400 to-red-500"
            : "text-white"
        }`}
    >
      {text}
      <span className="animate-pulse">|</span>
    </p>
  );
};

export default TypingText;
